use atlas_core::codara::artifact::census_container::{read, write, UNSEALED};
use atlas_core::{EpistemicStatus, IntegrityDigest, PersistenceKind, SemanticObservation};
use serde_json::{json, Value};
use std::{collections::BTreeSet, fs, path::Path};

fn main() {
    let args: Vec<_> = std::env::args().collect();
    assert_eq!(args.len(), 7, "container pack.json verify.json expected_revision expected_census output_directory");
    let bytes = fs::read(&args[1]).unwrap();
    let (atlas, root) = read(&bytes).unwrap();
    assert_eq!(write(&atlas).unwrap(), bytes, "complete decoded payload must re-encode to the exact actual file");
    let pack: Value = serde_json::from_slice(&fs::read(&args[2]).unwrap()).unwrap();
    let verified: Value = serde_json::from_slice(&fs::read(&args[3]).unwrap()).unwrap();
    assert_eq!(pack, verified, "actual pack/verify caller results must match completely");
    assert_eq!(pack["root_id"].as_str(), Some(root.as_str()));
    assert_eq!(pack["bytes"].as_u64(), Some(bytes.len() as u64));
    assert_eq!(pack["census_digest"].as_str(), Some(args[5].as_str()));
    assert_eq!(atlas.manifest.revision, format!("git:{}", args[4]));
    assert_eq!(IntegrityDigest::blake3_256(&atlas.manifest.census_digest).as_str(), args[5]);
    assert_eq!(atlas.manifest.seal, UNSEALED);
    assert!(atlas.seal.is_none());
    assert_eq!(atlas.manifest.certificate_id, atlas.certificate.certificate_id);
    assert!(atlas.certificate.blockers.iter().any(|b| b.starts_with("ATLAS_ROOT_UNSEALED")));

    let new_coordinate = "artifact:22fd555aa325f788";
    let old_coordinate = "artifact:d595dda1ddf8c19b";
    let coordinates: BTreeSet<_> = atlas.obligations.iter().map(|o| o.artifact.as_str()).collect();
    assert!(coordinates.contains(new_coordinate));
    assert!(!coordinates.contains(old_coordinate));
    let current_sync: Vec<_> = atlas.typed_records.iter().filter_map(|record| match record {
        SemanticObservation::Persistence(p) if p.status == EpistemicStatus::Derived
            && p.subject.kind == PersistenceKind::Sync
            && p.subject.span.path == "adapter/runtime/src/codara/container.rs" => Some(p),
        _ => None,
    }).collect();
    assert!(!current_sync.is_empty(), "actual current moved writer's DERIVED SYNC records must survive wire readback");
    assert!(!atlas.typed_records.iter().any(|record| matches!(record,
        SemanticObservation::Persistence(p) if p.subject.span.path == "adapter/runtime/src/atlas.rs"
    )));
    let evidence_ids: BTreeSet<_> = atlas.evidence.iter().map(|e| e.id.as_str()).collect();
    for record in &atlas.typed_records {
        for reference in record.evidence_refs() {
            assert!(evidence_ids.contains(reference.as_str()), "decoded typed evidence reference must resolve");
        }
    }
    for (field, count) in [("facts", atlas.facts.len()), ("obligations", atlas.obligations.len()),
        ("declared_nodes", atlas.nodes.len()), ("declared_edges", atlas.edges.len()),
        ("typed_records", atlas.typed_records.len()), ("evidence", atlas.evidence.len()), ("diagnostics", atlas.diagnostics.len())] {
        assert_eq!(pack[field].as_u64(), Some(count as u64));
    }
    assert_eq!(pack["certificate_state"].as_str(), Some(atlas.certificate.state.as_str()));

    // These are all fields of the existing decoded structs, not a new wire or authority type.
    // Preserve ordered collections and duplicate record IDs rather than deduplicating payload.
    let payload = json!({
        "manifest": {"genome_schema": atlas.manifest.genome_schema, "genome_hash": atlas.manifest.genome_hash,
            "census_digest": atlas.manifest.census_digest, "revision": atlas.manifest.revision,
            "certificate_id": atlas.manifest.certificate_id, "seal": atlas.manifest.seal,
            "tool": atlas.manifest.tool, "mode": atlas.manifest.mode},
        "facts": atlas.facts.iter().map(|f| json!({"id":f.id,"kind":f.kind,"status":f.status,
            "subject":f.subject,"predicate":f.predicate,"object":f.object,"source_path":f.source_path,
            "revision":f.revision,"extractor":f.extractor,"span":f.span})).collect::<Vec<_>>(),
        "obligations": atlas.obligations.iter().map(|o| json!({"artifact":o.artifact,"dimension":o.dimension,
            "extractor":o.extractor,"extractor_version":o.extractor_version,"status":o.status})).collect::<Vec<_>>(),
        "nodes": atlas.nodes.iter().map(|n| json!({"name":n.name,"kind":n.kind,"origin":n.origin})).collect::<Vec<_>>(),
        "edges": atlas.edges.iter().map(|e| json!({"from":e.from,"relation":e.relation,"to":e.to})).collect::<Vec<_>>(),
        "certificate":{"certificate_id":atlas.certificate.certificate_id,"state":atlas.certificate.state,"blockers":atlas.certificate.blockers},
        "typed_records":atlas.typed_records,"evidence":atlas.evidence,"diagnostics":atlas.diagnostics,"seal":atlas.seal,
    });
    let payload_bytes = serde_json::to_vec_pretty(&payload).unwrap();
    let out = Path::new(&args[6]);
    fs::create_dir_all(out).unwrap();
    fs::write(out.join("complete-decoded-payload.json"), &payload_bytes).unwrap();
    let record_ids: Vec<_> = payload["typed_records"].as_array().unwrap().iter().map(|r| {
        let inner = r.as_object().unwrap().values().next().unwrap();
        inner["record_id"].as_str().expect("every typed header retains its record ID").to_owned()
    }).collect();
    fs::write(out.join("decoded-identity-index.json"), serde_json::to_vec_pretty(&json!({
        "facts":atlas.facts.iter().map(|f| f.id.as_str()).collect::<Vec<_>>(),
        "obligation_artifact_coordinates":atlas.obligations.iter().map(|o| o.artifact.as_str()).collect::<Vec<_>>(),
        "typed_record_ids_with_multiplicity":record_ids,
        "evidence_ids":atlas.evidence.iter().map(|e| e.id.as_str()).collect::<Vec<_>>(),
        "diagnostic_ids":atlas.diagnostics.iter().map(|d| d.id.as_str()).collect::<Vec<_>>(),
    })).unwrap()).unwrap();
    let result = json!({"status":"PASS","revision":args[4],"manifest_revision":atlas.manifest.revision,
        "census_digest":args[5],"root_id":root.as_str(),"wire_bytes":bytes.len(),
        "wire_digest":IntegrityDigest::of_bytes(&bytes).as_str(),"decode_reencode_exact":true,
        "actual_pack_and_verify_results_equal":true,"complete_decoded_payload_digest":IntegrityDigest::of_bytes(&payload_bytes).as_str(),
        "current_artifact_coordinate":new_coordinate,"retired_path_coordinate_not_in_current_obligations":old_coordinate,
        "current_new_path_derived_sync_records":current_sync.len(),"all_typed_evidence_refs_resolve":true,
        "counts":{"facts":atlas.facts.len(),"obligations":atlas.obligations.len(),"typed_records":atlas.typed_records.len(),
            "evidence":atlas.evidence.len(),"diagnostics":atlas.diagnostics.len()},"seal":atlas.manifest.seal,
        "native_art1_scope":"Separate native registry witness; no art1 field invented inside CensusAtlas",
        "scope":"Read actual final-head local file through existing complete container reader; no authority, target admission or new shared wire"});
    fs::write(out.join("readback.json"), serde_json::to_vec_pretty(&result).unwrap()).unwrap();
    println!("{}", serde_json::to_string_pretty(&result).unwrap());
}
